   211→/**
   212→ * Try-on prompt template for showing outfit on fitting model (single image reference)
   213→ * Emphasizes maintaining exact face/body from reference while changing outfit
   214→ */
   215→function buildTryOnPrompt(items: Array<{ name: string; category: string; color?: string }>, outfitTitle?: string): string {
   216→  const itemDescriptions = items.map(item => {
   217→    const color = item.color ? `${item.color} ` : '';
   218→    return `${color}${item.name}`;
   219→  }).join(', ');
   220→
   221→  return `
   222→Photorealistic fashion catalog image. Reference photo shows the person - match face and body EXACTLY.
   223→
   224→FACE: Exact match to reference - same face shape, eyes, nose, mouth, skin tone, hair. No beautification.
   225→
   226→BODY: Match body type from reference exactly.
   227→
   228→OUTFIT: ${itemDescriptions}${outfitTitle ? ` (${outfitTitle})` : ''}
   229→
   230→POSE: Standing straight, facing camera, confident pose, feet together.
   231→
   232→MANDATORY BACKGROUND: Pure white infinity cove studio backdrop (RGB 255,255,255). Model floats in infinite white void - NO floor, NO ground, NO shadows on backdrop.
   233→
   234→LIGHTING: Bright front-facing softbox, high-key lighting to eliminate all shadows on backdrop.
   235→
   236→OUTPUT: E-commerce product photo quality, clean cutout-ready image, outfit clearly visible.
   237→`.trim();
   238→}
   239→
   240→/**
   241→ * Try-on prompt template for dual image reference (fitting model + flat-lay)
   242→ * IMAGE 1 is the fitting model (face/body reference)
   243→ * IMAGE 2 is the flat-lay showing exact outfit items to wear
   244→ */
