   252→Photorealistic fashion catalog image using TWO reference images:
   253→
   254→REFERENCE IMAGE 1: Shows the person - match face and body EXACTLY.
   255→REFERENCE IMAGE 2: Shows the flat-lay of outfit items - the model must wear the EXACT same items with matching colors, patterns, styles, and design details.
   256→
   257→FACE: Exact match to IMAGE 1 - same face shape, eyes, nose, mouth, skin tone, hair. No beautification.
   258→
   259→BODY: Match body type from IMAGE 1 exactly.
   260→
   261→OUTFIT: Wear the EXACT items shown in IMAGE 2. Copy every detail: ${itemDescriptions}${outfitTitle ? ` (${outfitTitle})` : ''}
   262→Do NOT modify, reinterpret, or change any aspect of the outfit. Match colors, patterns, cuts, and styling precisely.
   263→
   264→POSE: Standing straight, facing camera, confident pose, feet together.
   265→
   266→MANDATORY BACKGROUND: Pure white infinity cove studio backdrop (RGB 255,255,255). Model floats in infinite white void - NO floor, NO ground, NO shadows on backdrop.
   267→
   268→LIGHTING: Bright front-facing softbox, high-key lighting to eliminate all shadows on backdrop.
   269→
   270→OUTPUT: E-commerce product photo quality, clean cutout-ready image, outfit clearly visible and matching IMAGE 2 exactly.
   271→`.trim();
   272→}
   273→
   274→/**
   275→ * Fetches an image from URL and converts to base64 data URL
   276→ *
   277→ * @param imageUrl - URL of the image to fetch
   278→ * @returns Base64 data URL of the image
   279→ */
   280→async function fetchImageAsBase64(imageUrl: string): Promise<string> {
   281→  // If already a base64 data URL, return as-is
   282→  if (imageUrl.startsWith('data:image/')) {
   283→    return imageUrl;
   284→  }
   285→
   286→  // Fetch the image
   287→  const response = await fetch(imageUrl);
   288→  if (!response.ok) {
   289→    throw new Error(`Failed to fetch image: ${response.status}`);
   290→  }
   291→
   292→  const arrayBuffer = await response.arrayBuffer();
   293→  const base64 = Buffer.from(arrayBuffer).toString('base64');
   294→  const contentType = response.headers.get('content-type') || 'image/png';
   295→
   296→  return `data:${contentType};base64,${base64}`;
   297→}
   298→
   299→/**
   300→ * Generates a try-on looks image showing the recommended outfit on the user's fitting model
   301→ * Supports dual image reference when flat-lay image is provided for outfit consistency
   302→ *
   303→ * @param request - Try-on request with fitting model URL, outfit items, and optional flat-lay image
   304→ * @returns Promise resolving to fitting model response with try-on image
   305→ */
   306→export async function generateTryOnLooks(
   307→  request: TryOnLooksRequest
   308→): Promise<FittingModelResponse> {
   309→  try {
   310→    // Determine if we have a flat-lay image for dual reference mode
   311→    const flatLaySource = request.flatLayImageUrl || request.flatLayImageBase64;
   312→    const hasFlatLayImage = !!flatLaySource;
   313→
   314→    console.log('[FittingModel] Generating try-on looks:', {
   315→      fittingModelUrl: request.fittingModelImageUrl.substring(0, 50) + '...',
   316→      itemCount: request.outfitItems.length,
   317→      outfitTitle: request.outfitTitle,
   318→      hasFlatLayImage,
   319→      mode: hasFlatLayImage ? 'dual-reference' : 'single-reference',
   320→    });
   321→
   322→    // Validate input
   323→    if (!request.fittingModelImageUrl) {
   324→      return {
   325→        success: false,
   326→        error: 'MISSING_FITTING_MODEL',
   327→        message: 'Fitting model image is required for try-on generation',
   328→      };
   329→    }
   330→
   331→    if (!request.outfitItems || request.outfitItems.length === 0) {
   332→      return {
   333→        success: false,
   334→        error: 'MISSING_OUTFIT_ITEMS',
   335→        message: 'At least one outfit item is required for try-on generation',
   336→      };
   337→    }
   338→
   339→    // Fetch fitting model image and convert to base64
   340→    let fittingModelBase64: string;
   341→    try {
   342→      fittingModelBase64 = await fetchImageAsBase64(request.fittingModelImageUrl);
   343→    } catch (error) {
   344→      console.error('[FittingModel] Failed to fetch fitting model image:', error);
   345→      return {
   346→        success: false,
   347→        error: 'FETCH_FAILED',
   348→        message: 'Failed to load fitting model image',
   349→      };
   350→    }
   351→
   352→    // Fetch flat-lay image if available
   353→    let flatLayBase64: string | undefined;
   354→    if (hasFlatLayImage && flatLaySource) {
   355→      try {
   356→        flatLayBase64 = await fetchImageAsBase64(flatLaySource);
   357→        console.log('[FittingModel] Flat-lay image fetched successfully');
   358→      } catch (error) {
   359→        console.warn('[FittingModel] Failed to fetch flat-lay image, falling back to single reference:', error);
   360→        // Continue without flat-lay image - fallback to single reference mode
   361→      }
   362→    }
   363→
   364→    // Build the appropriate prompt based on whether we have dual reference
   365→    const useDualReference = !!flatLayBase64;
   366→    const prompt = useDualReference
   367→      ? buildDualReferenceTryOnPrompt(request.outfitItems, request.outfitTitle)
   368→      : buildTryOnPrompt(request.outfitItems, request.outfitTitle);
   369→
   370→    // Call the image generation API
   371→    const response = await fetch('/api/generate-image', {
   372→      method: 'POST',
   373→      headers: {
   374→        'Content-Type': 'application/json',
   375→      },
   376→      body: JSON.stringify({
   377→        description: prompt,
   378→        referenceImage: fittingModelBase64,
   379→        secondaryReferenceImage: flatLayBase64,
   380→        generationType: useDualReference ? 'try-on-dual' : 'try-on',
   381→        style: {
   382→          photographyStyle: 'professional studio',
   383→          composition: 'full-body frontal shot',
   384→          lighting: 'soft studio',
   385→          aestheticContext: 'clean minimal fashion',
   386→        },
   387→      }),
   388→    });
   389→
   390→    const data = await response.json();
   391→
   392→    if (!response.ok) {
   393→      console.error('[FittingModel] Try-on API error:', data);
   394→      return {
   395→        success: false,
   396→        error: data.error || 'GENERATION_FAILED',
   397→        message: data.message || 'Failed to generate try-on image',
   398→      };
   399→    }
   400→
   401→    if (data.success) {
   402→      console.log('[FittingModel] Try-on generation successful (mode:', useDualReference ? 'dual-reference' : 'single-reference', ')');
   403→      return {
   404→        success: true,
   405→        imageUrl: data.imageUrl,
   406→        imageBase64: data.imageBase64,
   407→        message: 'Try-on image generated successfully',
   408→      };
   409→    }
   410→
   411→    return {
   412→      success: false,
   413→      error: data.error || 'GENERATION_FAILED',
   414→      message: data.message || 'Failed to generate try-on image',
   415→    };
   416→  } catch (error) {
   417→    console.error('[FittingModel] Error generating try-on looks:', error);
   418→    return {
   419→      success: false,
